/// <summary>
/// CB223_PalletRounding
/// Contract class
/// </summary>
[DataContractAttribute]
class METSalesOrderCreditMgmtCheckContract extends METSysOperationTaskDataContract
{
    str packedQuery;
    guid topPickingProcessId;
    container   salesOrderCon;
    str         menuItemName;

}

Method.Source:
/// <summary>
/// contains the list of sales orders
/// </summary>
/// <param name = "_salesOrderCon">sales order container</param>
/// <returns>sales order container</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public container parmSalesOrderCon(container _salesOrderCon = salesOrderCon)
{
    salesOrderCon = _salesOrderCon;

    return salesOrderCon;
}

/// <summary>
/// parm method for MenuItem Name
/// </summary>
/// <param name = "_menuItemName">calling menu item name</param>
/// <returns>calling menu item name</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public str parmMenuItemName(str _menuItemName = menuItemName)
{
    menuItemName = _menuItemName;

    return menuItemName;
}

/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;

    return topPickingProcessId;
}

[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METSalesOrderCreditMgmtCheckQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}
